                            else if (expr[leftStart] === '(') parenCount--;
                            leftStart--;
                        }
                    } else {
                        leftStart--;
                    }
                }
                leftStart++;

                // Find the right operand (number or expression in parentheses)
                let rightEnd = powerIndex + 1;
                while (rightEnd < expr.length && (/\d|\./.test(expr[rightEnd]) || expr[rightEnd] === '(')) {
                    if (expr[rightEnd] === '(') {
